use crate::aap::caps::notifier;

struct Node;

/// Render the digest as the plain-text notification body. Only kept entries
/// are included; `considered` ids are not part of the message.
fn render(d: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest ");
    out.push_str(&d.date);
    out.push_str("\n\n");
    out.push_str(&d.overview);
    out.push('\n');
    for e in d.entries.iter().filter(|e| e.kept) {
        out.push_str("\n- ");
        out.push_str(&e.title);
        out.push_str(" (");
        out.push_str(&e.link);
        out.push_str(")\n  ");
        out.push_str(&e.summary);
        out.push('\n');
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
